function formatDateReadable(dateStr) {
  const options = { day: 'numeric', month: 'short' };
  return new Date(dateStr).toLocaleDateString('en-GB', options);
}


async function loadProjects() {
  const totalEl = root_element.querySelector('#total-projects-value');
  const runningEl = root_element.querySelector('#running-projects-value');
  const completedEl = root_element.querySelector('#completed-projects-value');

    const today = frappe.datetime.get_today();
    const yesterday = frappe.datetime.add_days(today, -1);


  try {
    const result = await frappe.call({
      method: 'frappe.client.get_list',
      args: {
        doctype: 'Production Project',
        fields: ['name', 'start_date', 'status'],
        filters: {
          start_date: ['between', [start, end]],
        },
        limit_page_length: 1000
      }
    });

    const projects = result.message || [];
    totalEl.innerHTML = projects.length.toLocaleString();
    runningEl.innerHTML = projects
        .filter(project => project.status === 'Open')
        .length
        .toLocaleString();
    console.log(projects)
    completedEl.innerHTML = projects
        .filter(project => project.status === 'Closed')
        .length
        .toLocaleString();    
  } catch (err) {
    console.error(err);
    totalEl.textContent = '⚠️ Error';
  }
}



function loadDashboardData() {
  loadProjects();
}

// Call once on page load
loadDashboardData();

// Auto-refresh every 15 seconds
setInterval(loadDashboardData, 15000);

const refresh_button = root_element.querySelector('#refresh-data');
if (refresh_button) {
  refresh_button.addEventListener('click', function () {
    loadDashboardData();
  });
}




const calendarBtn = root_element.querySelector('#calendar-trigger');
