const currentQuarterBtn = root_element.querySelector('#calendar-current-quarter-btn');
const currentYearBtn = root_element.querySelector('#calendar-current-year-btn');
const lastMonthBtn = root_element.querySelector('#calendar-last-month-btn');
const lastQuarterBtn = root_element.querySelector('#calendar-last-quarter-btn');
const lastYearBtn = root_element.querySelector('#calendar-last-year-btn');

const applyBtn = root_element.querySelector('#calendar-apply-btn');
const startInput = root_element.querySelector('#custom-date-start');
const endInput = root_element.querySelector('#custom-date-end');

function formatDate(dateObj) {
  const yyyy = dateObj.getFullYear();
  const mm = String(dateObj.getMonth() + 1).padStart(2, '0');
  const dd = String(dateObj.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function selectDateRange(option) {
  const today = new Date();
  let startDate, endDate;

  switch (option) {
    case "today":
      startDate = endDate = today;
      break;
    case "yesterday":
      startDate = endDate = new Date(today.setDate(today.getDate() - 1));
      break;
    case "last_week":
      const lastWeekStart = new Date(today);
      lastWeekStart.setDate(today.getDate() - today.getDay() - 6);
      const lastWeekEnd = new Date(today);
      lastWeekEnd.setDate(today.getDate() - today.getDay());
      startDate = lastWeekStart;
      endDate = lastWeekEnd;
      break;
    case "current_week":
      const weekStart = new Date(today);
      weekStart.setDate(today.getDate() - today.getDay() + 1);
      startDate = weekStart;
      endDate = new Date(); // today
      break;
    case "last_month":
      const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
      const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0);
      startDate = lastMonth;
      endDate = lastMonthEnd;
      break;
    case "current_month":
      const currentMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
      startDate = currentMonthStart;
      endDate = new Date(); // today
      break;
    case "current_quarter":
      const currentQuarter = Math.floor(today.getMonth() / 3);
      const currentQuarterStart = new Date(today.getFullYear(), currentQuarter * 3, 1);
      startDate = currentQuarterStart;
      endDate = new Date(); // today
      break;

    case "last_quarter":
      const currentQ = Math.floor(today.getMonth() / 3);
      const lastQuarterStart = new Date(today.getFullYear(), (currentQ - 1) * 3, 1);
      const lastQuarterEnd = new Date(today.getFullYear(), currentQ * 3, 0);
      startDate = lastQuarterStart;
      endDate = lastQuarterEnd;
      break;

    case "current_year":
      startDate = new Date(today.getFullYear(), 0, 1);
      endDate = new Date(); // today
      break;

    case "last_year":
      startDate = new Date(today.getFullYear() - 1, 0, 1);
      endDate = new Date(today.getFullYear() - 1, 11, 31);
      break;
    default:
      console.warn("Invalid date range option");
      return;
  }

  const formattedStart = formatDate(startDate);
  const formattedEnd = formatDate(endDate);

  startInput.value = formattedStart;
  endInput.value = formattedEnd;

  start = formattedStart;
  end = formattedEnd;

  loadDashboardData();
  calendarPopup.style.display = 'none';
}

calendarBtn.addEventListener('click', () => {
  calendarPopup.style.display = (calendarPopup.style.display === 'none') ? 'block' : 'none';
});

lastMonthBtn.addEventListener('click', () => selectDateRange('last_month'));
currentMonthBtn.addEventListener('click', () => selectDateRange('current_month'));
currentQuarterBtn.addEventListener('click', () => selectDateRange('current_quarter'));
lastQuarterBtn.addEventListener('click', () => selectDateRange('last_quarter'));
currentYearBtn.addEventListener('click', () => selectDateRange('current_year'));
lastYearBtn.addEventListener('click', () => selectDateRange('last_year'));

applyBtn.addEventListener('click', () => {
  const startDate = startInput.value;
  const endDate = endInput.value;

  if (!startDate || !endDate) {
    alert("Please select both start and end dates.");
    return;
  }

  if (startDate > endDate) {
    alert("Start date cannot be after end date.");
    return;
  }

  console.log("Selected date range:", startDate, "to", endDate);
  start = startDate;
  end = endDate;
  loadDashboardData();

  // You can now use these values to filter orders/payments/etc
  // frappe.call({ args: { start: startDate, end: endDate } });

  calendarPopup.style.display = 'none';
});

